  const dayOfWeek = date.getDay();
  let nextDate = new Date(date);
  nextDate.setDate(daysInMonth + 1);
  if (dayOfWeek >= 6) { // Saturday or Sunday
    nextDate.setDate(nextDate.getDate() - dayOfWeek);
  }
  return nextDate;
}
function getPreviousDay(date) {
  const daysInMonth = new Date(date.getFullYear(), date.getMonth(), 1).getDate();
  const dayOfWeek = date.getDay();
  let prevDate = new Date(date);
  prevDate.setDate(daysInMonth - 1);
  if (dayOfWeek <= 5) { // Friday or earlier
